// Drawings of the places stories happen in, generated by Recraft (fal.ai) as
// SVG so they sit in stage.html's vector world like the hand-drawn kitchen.
// One picture per style, to choose from, cached in ../art (not committed, like
// ../audio), so a re-run is free. The chosen one is tidied (things removed
// where `fx` acts, loud colours toned to the kitchen's) into ../places, which
// stage.html draws.
//   node places-art.mjs [shop] [--dry-run]

import { writeFile, mkdir } from 'node:fs/promises'
import { chromium } from 'playwright'

import { dryRun, estimate, picture } from '../../shared/fal.mjs'

const ROOT = new URL('../', import.meta.url).pathname
// The kitchen's colours, so a new place looks like the same world.
const colors = ['#8fb8a8', '#fbeedb', '#e7c9a0', '#b07a4f', '#f4f6f3', '#fde68a', '#f87171'].map((hex) => {
  const n = Number.parseInt(hex.slice(1), 16)
  return { r: n >> 16, g: (n >> 8) & 255, b: n & 255 }
})
const styles = ['vector_illustration', 'vector_illustration/roundish_flat', 'vector_illustration/emotional_flat', 'vector_illustration/vivid_shapes']

// `chosen` is the style picked; `drop` removes what lies wholly inside a box
// and `recolor` repaints a fill below a height, both in the picture's own
// units (2048 × 1536).
const places = {
  // Pak Hendra's toko kelontong: the counter stays bare, since the boxes and
  // supplier receipts are drawn on it and moved by `fx`.
  shop: {
    prompt: [
      'Interior of a small Indonesian neighbourhood grocery shop (toko kelontong), seen straight on from the front, flat and simple.',
      'A long wooden counter across the lower third, its top completely empty and clear.',
      'Behind it, tall wooden shelves with neat rows of plain packaged goods, jars, bottles and stacked instant noodle packs, sacks of rice on the floor at one side, a small glass display case, a wall fan.',
      'Warm daylight, calm, soft flat colours, no outlines, no shadows.',
      'No people. No text, no letters, no signs, no logos, no brand names anywhere.',
    ].join(' '),
    chosen: 'vivid_shapes',
    // A striped crate on the counter, where the supplier boxes land.
    drop: [[1370, 660, 1820, 860]],
    // The coral floor tiles, in the kitchen floor's wood.
    recolor: [{ from: 'rgb(248,113,113)', below: 1340, to: '#dcb98c' }],
  },
}

const tidy = async (browser, source, { drop = [], recolor = [] }) => {
  const page = await browser.newPage()
  await page.goto(`file://${source}`)
  const svg = await page.evaluate(({ drop, recolor }) => {
    const root = document.querySelector('svg')
    for (const node of [...root.children]) {
      if (!node.getBBox) continue
      const box = node.getBBox()
      if (drop.some(([x0, y0, x1, y1]) => box.x >= x0 && box.y >= y0 && box.x + box.width <= x1 && box.y + box.height <= y1)) node.remove()
      for (const { from, below, to } of recolor) if (node.getAttribute('fill') === from && box.y >= below) node.setAttribute('fill', to)
    }
    return root.outerHTML
  }, { drop, recolor })
  await page.close()
  return svg
}

const only = process.argv.slice(2).filter((arg) => !arg.startsWith('--'))
const browser = dryRun ? undefined : await chromium.launch({ channel: 'chrome' })
for (const [place, { prompt, chosen, ...edits }] of Object.entries(places)) {
  if (only.length > 0 && !only.includes(place)) continue
  for (const style of styles) {
    const name = `${place}-${style.split('/').at(-1)}`
    const path = await picture({
      dir: `${ROOT}art`,
      project: 'catatsaja',
      name,
      model: 'fal-ai/recraft/v3/text-to-image',
      input: { prompt, style, image_size: 'landscape_4_3', colors },
    })
    if (!path) continue
    console.log(path)
    if (browser && style.endsWith(chosen)) {
      await mkdir(`${ROOT}places`, { recursive: true })
      await writeFile(`${ROOT}places/${place}.svg`, await tidy(browser, path, edits))
      console.log(`→ places/${place}.svg`)
    }
  }
}
await browser?.close()
if (dryRun) estimate()
